function appendLinks(parent,text){const re=/https?:\/\/[^\s<>"']+|\[[^\]\n]+\]\(https?:\/\/[^\s<>]+\)/g;let last=0;for(const match of text.matchAll(re)){parent.append(document.createTextNode(text.slice(last,match.index)));let label=match[0],url=label,suffix='';const md=/^\[([^\]]+)\]\((.+)\)$/.exec(label);if(md){label=md[1];url=md[2];}else{url=url.replace(/[.,;:!?]+$/,'');while(url.endsWith(')')&&(url.match(/\)/g)||[]).length>(url.match(/\(/g)||[]).length)url=url.slice(0,-1);suffix=label.slice(url.length);label=url;}try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw Error();parent.append(el('a',{href:parsed.href,target:'_blank',rel:'noopener noreferrer'},label),document.createTextNode(suffix));}catch{parent.append(document.createTextNode(match[0]));}last=match.index+match[0].length;}parent.append(document.createTextNode(text.slice(last)));}
