const queuedFiles=restoredView.files||{},fileBlobs=new Map();let uploading=0;
const fileInput=el('input',{type:'file',multiple:'',hidden:''});
const fileTray=el('div',{class:'attachment-tray'});$('#composer').prepend(fileTray);$('#composer').append(fileInput);
const attachButton=button('',()=>fileInput.click(),'icon-button attach-button');attachButton.append(icon('clip'));attachButton.setAttribute('aria-label',t('Anexar'));attachButton.title=t('Anexar');$('.composer-footer').prepend(attachButton);
