function fileURL(f){return API+'/api/files/'+encodeURIComponent(f.id);}
function attachmentPreview(files,removable=false){const box=el('div',{class:'attachment-grid'});for(const f of files){const card=el('div',{class:'attachment-card'}),url=fileURL(f);if(f.mime?.startsWith('image/')){const img=el('img',{src:url,alt:f.name,loading:'lazy'});const link=el('a',{href:url,target:'_blank',rel:'noopener'});link.append(img);card.append(link);}else if(f.mime?.startsWith('video/'))card.append(el('video',{src:url,controls:'',preload:'metadata',playsinline:''}));else if(f.mime?.startsWith('audio/'))card.append(el('audio',{src:url,controls:'',preload:'metadata'}));else if(f.mime==='application/pdf'){card.append(button(t('Prévia do PDF'),()=>{const view=el('div');view.append(el('iframe',{src:url,title:f.name,class:'document-preview'}),el('a',{href:url,target:'_blank',rel:'noopener'},t('Abrir documento')));openDialog(f.name,view);}));}else card.append(el('span',{class:'file-symbol'},t('Arquivo')));
card.append(el('a',{href:url,target:'_blank',rel:'noopener',class:'file-name'},f.name),el('small',{},new Intl.NumberFormat(locale(),{maximumFractionDigits:1}).format(f.size/1024/1024)+' MB'));if(removable)card.append(button(t('Remover'),()=>{queuedFiles[selected]=(queuedFiles[selected]||[]).filter(x=>x.id!==f.id);renderFiles();}));box.append(card);}return box;}
function renderFiles(){fileTray.replaceChildren(attachmentPreview(queuedFiles[selected]||[],true));if(uploading)fileTray.append(el('p',{role:'status'},t('Enviando anexo…')));}
async function addFiles(files){const target=selected;for(const file of files){if((queuedFiles[target]||[]).length>=10){toast('Use até 10 anexos por mensagem.');break;}if(file.size>100*1024*1024){toast(t('{name}: limite de 100 MB por arquivo.',{name:file.name}));continue;}uploading++;renderFiles();try{const response=await fetch(API+'/api/uploads?name='+encodeURIComponent(file.name),{method:'POST',headers:device&&!remoteMode?{Authorization:'Bearer '+device}:{},body:file,credentials:local?'same-origin':'omit',signal:AbortSignal.timeout(180000)});const result=await response.json();if(!response.ok)throw Error(result.error);(queuedFiles[target]??=[]).push(result);}catch(e){toast(t('Anexo não enviado: {error}',{error:t(e.message)}));}finally{uploading--;renderFiles();}}}
$('#prompt').addEventListener('paste',e=>{const files=[...(e.clipboardData?.files||[])];if(files.length){e.preventDefault();void addFiles(files);}});
