const mentions=el('div',{id:'mentions',role:'listbox',class:'mention-menu',hidden:''});$('#composer').prepend(mentions);$('#prompt').setAttribute('aria-controls','mentions');$('#prompt').setAttribute('aria-autocomplete','list');let mentionItems=[],mentionIndex=0,mentionStart=0;
function mentionMenu(){const p=$('#prompt'),before=p.value.slice(0,p.selectionStart),match=/(?:^|\s)@([^@\n]{0,80})$/.exec(before);if(!match){mentions.hidden=true;return;}mentionStart=before.lastIndexOf('@');const pool=channel()?state.agents.filter(a=>channel().members.includes(a.id)):state.agents;mentionItems=pool.filter(a=>a.name.toLocaleLowerCase().includes(match[1].toLocaleLowerCase())).slice(0,8);mentionIndex=0;drawMentions();}
function drawMentions(){mentions.replaceChildren();mentions.hidden=!mentionItems.length;$('#prompt').setAttribute('aria-expanded',String(!mentions.hidden));mentionItems.forEach((a,i)=>{const b=button(a.name,()=>insertMention(a),'mention-option');b.id='mention-'+i;b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===mentionIndex));b.onmousedown=e=>e.preventDefault();mentions.append(b);});if(mentionItems.length)$('#prompt').setAttribute('aria-activedescendant','mention-'+mentionIndex);}
function insertMention(a){const p=$('#prompt'),end=p.selectionStart;p.setRangeText('@'+a.name+' ',mentionStart,end,'end');mentions.hidden=true;mentionItems=[];p.removeAttribute('aria-activedescendant');p.focus();saveDraft();resizePrompt();}
function mentionKey(e){if(mentions.hidden)return false;if(e.key==='Escape'){mentions.hidden=true;return true;}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();mentionIndex=(mentionIndex+(e.key==='ArrowDown'?1:-1)+mentionItems.length)%mentionItems.length;drawMentions();return true;}if(['Enter','Tab'].includes(e.key)){e.preventDefault();insertMention(mentionItems[mentionIndex]);return true;}return false;}
function field(box,label,value='',multiline=false){const id='field-'+crypto.randomUUID(),input=el(multiline?'textarea':'input',{id,...(multiline?{rows:'7'}:{})});input.value=value;box.append(el('label',{for:id},label),input);return input;}
function choices(box,items,selectedIds=[]){const wrap=el('div',{class:'checkbox-list'}),inputs=[];for(const item of items){const label=el('label'),input=el('input',{type:'checkbox',value:item.id});input.checked=selectedIds.includes(item.id);label.append(input,document.createTextNode(item.name));wrap.append(label);inputs.push(input);}box.append(wrap);return ()=>inputs.filter(i=>i.checked).map(i=>i.value);}
function editAgent(a){const box=el('div'),name=field(box,t('Nome'),a?.name),description=field(box,t('Papel e instruções'),a?.description,true);box.append(el('h3',{},t('Skills do agente')));const skills=choices(box,state.skills,a?.skills);const browser=el('input',{type:'checkbox'});browser.checked=a?.browser===true;const label=el('label');label.append(browser,document.createTextNode(t(' Usa navegador (execução exclusiva)')));box.append(label,button(t('Salvar agente'),async()=>{const result=await api('agents',{id:a?.id,name:name.value,description:description.value,skills:skills(),browser:browser.checked});$('#dialog').close();await refresh();selectAgent(result.id);toast('Agente salvo.');},'primary'));openDialog(a?t('Editar agente'):t('Novo agente'),box);}
function editChannel(c){const box=el('div'),name=field(box,t('Nome do canal'),c?.name),description=field(box,t('Objetivo'),c?.description);box.append(el('p',{},t('Sem menções, todos os participantes respondem. Use @ para chamar apenas agentes específicos.')),el('h3',{},t('Participantes')));const members=choices(box,state.agents,c?.members);box.append(button(t('Salvar canal'),async()=>{const result=await api('channels',{id:c?.id,name:name.value,description:description.value,members:members()});$('#dialog').close();await refresh();selectAgent('channel:'+result.id);},'primary'));openDialog(c?t('Editar canal'):t('Novo canal'),box);}
function editSkill(s){const box=el('div'),name=field(box,t('Nome'),s?.name),description=field(box,t('Descrição'),s?.description),instructions=field(box,t('Instruções completas (Markdown)'),s?.instructions,true);instructions.classList.add('skill-editor');box.append(button(t('Salvar skill'),async()=>{await api('skills',{id:s?.id,name:name.value,description:description.value,instructions:instructions.value});$('#dialog').close();await refresh();toast('Skill salva. Associe-a ao agente em Editar agente.');},'primary'));openDialog(s?t('Editar skill'):t('Nova skill'),box);}
